begin;
set local search_path=public,extensions;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000003','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','batch','observed_at',now(),'payload','{}'::jsonb))->>'status','conflict','Manager cannot create a production batch');
select throws_ok($$select public.close_deviation((select id from public.deviation where severity='critical' limit 1),'closed',gen_random_uuid())$$,'P0001','Review permission required','Manager cannot close critical deviation');
select throws_ok($$select public.manage_account('20000000-0000-4000-8000-000000000001','active',array['admin'],'{}','grant privilege')$$,'P0001','Managers cannot grant global roles','Manager cannot escalate a user to global admin');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','training','observed_at',now(),'payload',jsonb_build_object('module_id','70000000-0000-4000-8000-000000000001','score',100)))->>'status','conflict','A claimed perfect score without answers cannot grant training');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','training','observed_at',now(),'payload',jsonb_build_object('module_id','70000000-0000-4000-8000-000000000001','answers','{"hygiene":"safe"}'::jsonb)))->>'status','synced','Server verifies assessment answers');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','sale','observed_at',now(),'payload',jsonb_build_object('packaging_lot_id','60000000-0000-4000-8000-000000000003','quantity',1000000,'transaction_type','return','customer_category','retail','total',1,'currency','USD','usd_rate',1)))->>'status','conflict','Returns cannot inflate stock beyond prior outbound units');
select ok(not exists(select 1 from public.lot_balances() b join public.lot l using(id) where l.cooperative_id='10000000-0000-4000-8000-000000000002'),'Balance query respects cooperative isolation');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','deviation','observed_at',now(),'payload',jsonb_build_object('lot_id','60000000-0000-4000-8000-000000002012','severity','minor','category','manual','issue','cross-cooperative write attempt')))->>'status','conflict','A deviation cannot reference another cooperative lot');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','allocation','observed_at',now(),'payload',jsonb_build_object('input_lot_id','60000000-0000-4000-8000-000000000006','output_lot_id','60000000-0000-4000-8000-000000000008','quantity',1,'unit','kg')))->>'status','conflict','Rejected whey cannot be allocated');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','allocation','observed_at',now(),'payload',jsonb_build_object('input_lot_id','60000000-0000-4000-8000-000000000005','output_lot_id','60000000-0000-4000-8000-000000000008','quantity',1,'unit','kg')))->>'status','conflict','Held whey cannot be allocated');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','sale','observed_at',now(),'payload',jsonb_build_object('packaging_lot_id','60000000-0000-4000-8000-000000000003','quantity',1000000,'transaction_type','sale','customer_category','retail','total',1,'currency','USD','usd_rate',1)))->>'status','conflict','Sale exceeding stock is rejected');
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000001','author_id','20000000-0000-4000-8000-000000000001','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','checkpoint','observed_at',now(),'payload',jsonb_build_object('lot_id','60000000-0000-4000-8000-000000000002','definition_key','drying_temperature','values',jsonb_build_object('value',9999,'unit','°C'))))->>'status','conflict','Physically implausible measurement requires re-entry');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.transition_lot('60000000-0000-4000-8000-000000000009','released','complete review',public.pin_signoff('2468','30000000-0000-4000-8000-000000000001','decision','60000000-0000-4000-8000-000000000009'))$$,'P0001','Required records missing','Missing required checkpoints block release');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000006","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::integer from public.lot where cooperative_id='10000000-0000-4000-8000-000000000002'),0,'Partner without cooperative consent cannot inspect another cooperative');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000007","role":"authenticated","aal":"aal1"}',true);
select lives_ok($$select public.register_device('30000000-0000-4000-8000-000000000007','Donor test device')$$,'Donor can register a viewer session device');
select ok(public.pin_signoff('2468','30000000-0000-4000-8000-000000000007','cache_session','20000000-0000-4000-8000-000000000007') is not null,'Donor can verify PIN for a cached session');
select throws_ok($$select public.pin_signoff('2468','30000000-0000-4000-8000-000000000007','decision','60000000-0000-4000-8000-000000000002')$$,'P0001','Not authorized','Donor session PIN cannot authorize a critical operation');
select ok((select bool_and((metric->>'suppressed')::boolean) from public.impact_metrics('2026-01-01','2026-12-31') metric),'Donor groups below five producers are suppressed');
select ok(not exists(select 1 from public.impact_metrics('2026-01-01','2026-12-31') metric where metric->>'id' in ('KPI-06','KPI-09','KPI-12','KPI-13')),'Donor sees only dictionary-approved indicators');
select set_config('request.jwt.claims','{"sub":"20000000-0000-4000-8000-000000000005","role":"authenticated","aal":"aal2"}',true);
select is(public.apply_sync(jsonb_build_object('id',gen_random_uuid(),'cooperative_id','10000000-0000-4000-8000-000000000002','author_id','20000000-0000-4000-8000-000000000005','device_id','30000000-0000-4000-8000-000000000001','config_version_id','40000000-0000-4000-8000-000000000001','action','deviation','observed_at',now(),'payload',jsonb_build_object('lot_id','60000000-0000-4000-8000-000000002012','severity','minor','category','manual','issue','Authorized cross-cooperative food safety review')))->>'status','synced','Food-Safety Lead with MFA can raise a scoped cross-cooperative deviation');
reset role;
select is((select count(*)::integer from public.kpi_definition),13,'KPI dictionary contains all thirteen PRD definitions');
select ok(not has_function_privilege('authenticated','public.bootstrap_installation(uuid,jsonb,jsonb,jsonb)','execute'),'Application users cannot invoke owner bootstrap');
select ok(not has_function_privilege('anon','public.bootstrap_installation(uuid,jsonb,jsonb,jsonb)','execute'),'Anonymous users cannot bootstrap an installation');
select * from finish();rollback;
